// === Tab: Main ===
let xoff, yoff, zoff, inc, col;
let rez, cols, rows, num;
let vectors;
ArrayList<Particle> particles;
function setup() {
	createCanvas(700, 500);
  colorMode(HSB);
  init();
}
function init() {
  background(0);
  rez = 10;
  inc = 0.1;
  num = 200;
  col = random(255);
  cols = floor(width / rez) + 1;
  rows = floor(height / rez) + 1;
  vectors = new Array(cols * rows);
  particles = new ArrayList<Particle>();
  for (i=0; i<num; i++)
    particles.add(new Particle());
}
function draw() {
  yoff = 0;
  for (y=0; y<rows; y++) {
    xoff = 0;
    for (x=0; x<cols; x++) {
      let angle = noise(xoff, yoff, zoff) * TWO_PI * 2;
      let v = PVector.fromAngle(angle);
      v.setMag(1);
      vectors[x + y * cols] = v;
      xoff += inc;
    }
    yoff += inc;
  }
  zoff += 0.005;
  if (col < 255)col += 0.1;
  else col = 0;
  for (let p of particles)p.run();
}
function mousePressed()
{
  background(000);
  init();
}

// === Tab: Particle ===
class Particle {
  pos, vel, acc, prev;
  let max = random(2, 8);
  constructor() {
    pos = new PVector(width/2, height/2);
    prev = new PVector(pos.x, pos.y);
    vel = new PVector(0, 0);
    acc = new PVector(0, 0);
  }
  function copy() {
		prev.x = pos.x;
		prev.y = pos.y;
	}
  function run() {
    follow();
    update();
    show();
  }
  function update() {
    pos.add(vel);
    vel.limit(max);
    vel.add(acc);
    acc.mult(0);
    if (pos.x > width) {
      pos.x = 0; 
      copy();
    }  
    if (pos.x < 0) {
      pos.x = width; 
      copy();
    } 
    if (pos.y > height) {
      pos.y = 0; 
      copy();
    }  
    if (pos.y < 0) {
      pos.y = height; 
      copy();
    }
  }
  function follow() {
    let x = floor(pos.x / rez);
    let y = floor(pos.y / rez);
    let force = vectors[x + y * cols];
    acc.add(force);
  }
  function show() {
    stroke(col, 255, 255, 5);
    line(pos.x, pos.y, prev.x, prev.y);
    copy();
  }
}

